import { MakeLogicType, afterMount, connect, kea, listeners, path } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { signalsReportsList } from 'products/signals/frontend/generated/api'

import { inboxBulkActionsLogic } from './inboxBulkActionsLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface forYouCountLogicValues {
    currentTeamId: number | null // teamLogic
    forYouCount: number | null
    forYouCountLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface forYouCountLogicActions {
    reportClaimChanged: (
        reportId: string,
        assignee: null | import('../../generated/api.schemas').SignalReportAssigneeApi | undefined
    ) => {
        assignee: null | import('../../generated/api.schemas').SignalReportAssigneeApi | undefined
        reportId: string
    } // inboxBulkActionsLogic
    reportStateChanged: () => {
        value: true
    } // inboxBulkActionsLogic
    loadForYouCount: () => any
    loadForYouCountFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadForYouCountSuccess: (
        forYouCount: number,
        payload?: any
    ) => {
        forYouCount: number
        payload?: any
    }
}

export type forYouCountLogicType = MakeLogicType<forYouCountLogicValues, forYouCountLogicActions>

/** How many reports the server puts in the person's "For you" list, for the inbox header. */
export const forYouCountLogic = kea<forYouCountLogicType>([
    path(['products', 'signals', 'forYouCountLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeamId']],
        actions: [inboxBulkActionsLogic, ['reportStateChanged', 'reportClaimChanged']],
    })),
    loaders(({ values }) => ({
        forYouCount: [
            null as number | null,
            {
                loadForYouCount: async (): Promise<number> =>
                    (
                        await signalsReportsList(String(values.currentTeamId), {
                            view: 'for_you',
                            count_only: true,
                            limit: 1,
                        })
                    ).count,
            },
        ],
    })),
    listeners(({ actions }) => ({
        reportStateChanged: () => actions.loadForYouCount(),
        reportClaimChanged: () => actions.loadForYouCount(),
    })),
    afterMount(({ actions }) => {
        actions.loadForYouCount()
    }),
])
